package replay

import (
	"encoding/binary"
	"errors"
	"fmt"
	"math"
	"strings"
	"time"
)

// Encode is FUN_00429b60's file writer without filesystem or timing side
// effects. Raw reserved bytes and USER blocks survive Decode -> Encode;
// compressed data is always regenerated by FUN_004359b0's tree algorithm.
// Callers creating a new replay set Global.Timestamp explicitly. Raw trailer
// bytes are authoritative; clear Trailer.Raw when changing its metadata.
func Encode(r *Replay) ([]byte, error) {
	if r == nil {
		return nil, errors.New("replay: cannot encode nil replay")
	}
	if r.Header.Version != 0 && r.Header.Version != Version {
		return nil, fmt.Errorf("replay: unsupported version %d", r.Header.Version)
	}
	payload, err := encodePayload(r)
	if err != nil {
		return nil, err
	}
	comp := lzssCompress(payload)
	// FUN_00429b60: inverse passes in the reverse order of FUN_0042a200.
	xorEncrypt(comp, 0x7a, 0x80, 0x3d)
	xorEncrypt(comp, 0xe1, 0x400, 0xaa)
	h, err := rawBlock(r.Header.Raw, 0x24)
	if err != nil {
		return nil, err
	}
	if len(r.Header.Raw) == 0 {
		// FUN_00428f60, 0x428f9a..0x428fce: version 5, +0x10 = 0x100,
		// every other reserved word zero. Version 5 writes no checksum.
		binary.LittleEndian.PutUint32(h[0x10:], 0x100)
	}
	copy(h, Magic)
	binary.LittleEndian.PutUint32(h[4:], Version)
	binary.LittleEndian.PutUint32(h[0x0c:], uint32(0x24+len(comp)+len(r.BeforeTrailer)))
	binary.LittleEndian.PutUint32(h[0x1c:], uint32(len(comp)))
	binary.LittleEndian.PutUint32(h[0x20:], uint32(len(payload)))
	trailer := r.Trailer.Raw
	if len(trailer) == 0 {
		trailer = encodeTrailer(r)
	}
	out := make([]byte, 0, len(h)+len(comp)+len(r.BeforeTrailer)+len(trailer))
	out = append(out, h...)
	out = append(out, comp...)
	out = append(out, r.BeforeTrailer...)
	out = append(out, trailer...)
	return out, nil
}

func rawBlock(raw []byte, size int) ([]byte, error) {
	if len(raw) != 0 && len(raw) != size {
		return nil, fmt.Errorf("replay: raw block has %d bytes, want %d", len(raw), size)
	}
	b := make([]byte, size)
	copy(b, raw)
	return b, nil
}

// encodePayload is FUN_00429b60's global/header/records/slow-rates copy order.
func encodePayload(r *Replay) ([]byte, error) {
	b, err := rawBlock(r.Global.Raw, globalHeaderSize)
	if err != nil {
		return nil, err
	}
	g := r.Global
	if len(g.User) > 8 || strings.ContainsAny(g.User, "\r\n\x00") {
		return nil, errors.New("replay: name must fit eight bytes without line breaks or NUL")
	}
	if len(g.Raw) == 0 || g.User != parseGlobalHeader(g.Raw).User {
		copy(b[:8], "        ")
		copy(b[:8], g.User)
		b[8] = 0
	}
	binary.LittleEndian.PutUint32(b[0x0c:], uint32(g.Timestamp))
	binary.LittleEndian.PutUint32(b[0x10:], uint32(g.Score))
	binary.LittleEndian.PutUint32(b[0x48:], math.Float32bits(g.SlowRate))
	chapters := g.Chapters
	if chapters == 0 {
		chapters = uint32(len(r.Chapters))
	}
	binary.LittleEndian.PutUint32(b[0x4c:], chapters)
	binary.LittleEndian.PutUint32(b[0x50:], g.Character)
	binary.LittleEndian.PutUint32(b[0x54:], g.ShotType)
	binary.LittleEndian.PutUint32(b[0x58:], g.Difficulty)
	binary.LittleEndian.PutUint32(b[0x5c:], g.Stage)
	for i := range r.Chapters {
		ch := &r.Chapters[i]
		h, err := ChapterHeader(*ch)
		if err != nil {
			return nil, fmt.Errorf("replay: chapter %d: %w", i, err)
		}
		b = append(b, h...)
		for _, rec := range ch.Records {
			b = binary.LittleEndian.AppendUint16(b, rec.Keys)
			b = binary.LittleEndian.AppendUint16(b, rec.Aux1)
			b = binary.LittleEndian.AppendUint16(b, rec.Aux2)
		}
		if len(ch.SlowRates) == 0 {
			for range slowRateSamples(len(ch.Records)) {
				b = append(b, 0xff)
			}
		} else {
			b = append(b, ch.SlowRates...)
		}
		b = append(b, ch.Padding...)
	}
	b = append(b, r.PayloadTail...)
	if len(b) > 64<<20 {
		return nil, errors.New("replay: payload exceeds 64 MiB")
	}
	return b, nil
}

// ChapterHeader serializes FUN_00428f60 / FUN_0042a450's snapshot and
// FUN_00429b60's counts. The opaque player history/option fields in Raw are
// retained; known fields always come from the Chapter's typed values.
func ChapterHeader(ch Chapter) ([]byte, error) {
	b, err := rawBlock(ch.Raw, chapterHeaderSize)
	if err != nil {
		return nil, err
	}
	n := len(ch.Records)
	samples := slowRateSamples(n)
	if len(ch.SlowRates) != 0 && len(ch.SlowRates) != samples {
		return nil, fmt.Errorf("slow-rate samples %d, want %d", len(ch.SlowRates), samples)
	}
	count := ch.FrameCount
	if count == 0 {
		count = uint32(n)
	}
	binary.LittleEndian.PutUint16(b, ch.Index)
	binary.LittleEndian.PutUint16(b[2:], ch.Seed)
	binary.LittleEndian.PutUint32(b[4:], count)
	binary.LittleEndian.PutUint32(b[8:], uint32(n*recordSize+samples+len(ch.Padding)))
	binary.LittleEndian.PutUint32(b[0x0c:], uint32(ch.Score))
	binary.LittleEndian.PutUint16(b[0x10:], uint16(ch.Power))
	binary.LittleEndian.PutUint32(b[0x14:], uint32(ch.Faith))
	binary.LittleEndian.PutUint32(b[0x18:], uint32(ch.Hold))
	binary.LittleEndian.PutUint32(b[0x1c:], uint32(ch.Lives))
	binary.LittleEndian.PutUint32(b[0x20:], uint32(ch.Rank))
	binary.LittleEndian.PutUint32(b[0x24:], uint32(ch.PlayerX))
	binary.LittleEndian.PutUint32(b[0x28:], uint32(ch.PlayerY))
	binary.LittleEndian.PutUint32(b[0x1b4:], uint32(ch.State90))
	binary.LittleEndian.PutUint32(b[0x1b8:], uint32(ch.State9C))
	binary.LittleEndian.PutUint32(b[0x1bc:], uint32(ch.Focus))
	binary.LittleEndian.PutUint32(b[0x1c0:], ch.Flags)
	return b, nil
}

// USER text constants are the Shift-JIS bytes at 0x46e5e0 and 0x46e4f8;
// they are data, not runtime reads from an installation.
const replayInfo = "\x93\x8c\x95\xfb\x95\x97\x90\x5f\x98\x5e \x83\x8a\x83\x76\x83\x8c\x83\x43\x83\x74\x83\x40\x83\x43\x83\x8b\x8f\xee\x95\xf1\r\n"
const replayComment = "\x83\x52\x83\x81\x83\x93\x83\x67\x82\xf0\x8f\x91\x82\xaf\x82\xdc\x82\xb7"

// encodeTrailer ports the two USER chunks of FUN_00429b60. Chunk length
// includes the 12-byte prefix, NUL, and padding to a dword boundary.
func encodeTrailer(r *Replay) []byte {
	g, t := r.Global, r.Trailer
	date := t.Date
	if date == "" {
		date = time.Unix(int64(g.Timestamp), 0).Format("06/01/02 15:04")
	}
	name := fmt.Sprintf("%-8s", g.User)
	chara := fmt.Sprintf("%s%c", []string{"Reimu", "Marisa"}[min(g.Character, 1)], 'A'+min(g.ShotType, 2))
	rank := []string{"Easy   ", "Normal ", "Hard   ", "Lunatic", "Extra  "}[min(g.Difficulty, 4)]
	first, last := uint16(g.Stage), uint16(g.Stage)
	if len(r.Chapters) != 0 {
		first, last = r.Chapters[0].Index, r.Chapters[len(r.Chapters)-1].Index
	}
	stage := fmt.Sprintf("Stage %d\r\n", last)
	if g.Stage >= 8 {
		stage = "Stage All Clear\r\n"
		if first == 7 {
			stage = "Extra Stage Clear\r\n"
		}
	} else if first != last {
		stage = fmt.Sprintf("Stage %d to %d\r\n", first, last) // 0x46e52c
	} else if first == 7 {
		stage = "Extra Stage\r\n"
	}
	text := fmt.Sprintf("%sVersion 1.00a\r\nName %s\r\nDate %s\r\nChara %-7s\r\nRank %s\r\n%sScore %d\r\nSlow Rate %2.2f\r\n",
		replayInfo, name, date, chara, rank, stage, g.Score, g.SlowRate)
	return append(userBlock(0, text), userBlock(1, replayComment)...)
}

func userBlock(kind byte, text string) []byte {
	b := make([]byte, (12+len(text)+1+3)&^3)
	copy(b, "USER")
	binary.LittleEndian.PutUint32(b[4:], uint32(len(b)))
	b[8] = kind
	copy(b[12:], text)
	return b
}
